import{_ as d,o as n,c as a,a4 as t}from"./chunks/framework.BE47AOxC.js";const p=JSON.parse(`{"title":"ADR-0004 — Modèle d'embedding par défaut","description":"Extrait de docs/adr/0004-modele-embedding-par-defaut.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0004 — Modèle d'embedding par défaut","description":"Extrait de docs/adr/0004-modele-embedding-par-defaut.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0004-modele-embedding-par-defaut.md","filePath":"developpeurs/adr/0004-modele-embedding-par-defaut.md"}`),i={name:"developpeurs/adr/0004-modele-embedding-par-defaut.md"};function o(r,e,s,c,l,u){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0004--modèle-dembedding-par-défaut" tabindex="-1">ADR-0004 — Modèle d&#39;embedding par défaut <a class="header-anchor" href="#adr-0004--modèle-dembedding-par-défaut" aria-label="Permalink to &quot;ADR-0004 — Modèle d&#39;embedding par défaut {#adr-0004--modèle-dembedding-par-défaut}&quot;">​</a></h1><p><strong>Date :</strong> 19 août 2026 <strong>Statut :</strong> Accepté avec garde-fou (décision de fond différée à l&#39;Epic E8) — <strong>décision de fond prise par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0037-modele-embedding-par-defaut-bge-m3">ADR-0037</a></strong><strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> CDC_CMS_AI_Native_v1.1 §14.2, §14.3, §17 point ouvert #4 ; plan d&#39;action agile §3.1.bis</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>Le CDC signale ce point comme un piège classique de mise en production : <em>« changer de modèle d&#39;embedding invalide tout l&#39;index vectoriel existant »</em> (§14.2). Le champ <code>dimensions</code> est déclaré au niveau de la capacité <code>EmbeddingCapability</code> précisément parce que la dimension contraint le schéma <code>pgvector</code> (<code>ai_embeddings.embedding vector(768)</code> dans le modèle de données §14.5).</p><p>Le CDC est également explicite sur l&#39;absence de données pour trancher maintenant : <em>« Aucun test, aucun benchmark. Les noms de modèles sont volontairement laissés en placeholders dans le registre »</em> (Annexe D). Choisir un modèle aujourd&#39;hui reviendrait à figer une dimension <code>pgvector</code> sur la base d&#39;aucune donnée de performance réelle en français.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>Le choix du modèle d&#39;embedding par défaut est différé à l&#39;Epic E8 (AI Socle, jalon M8a)</strong>, où il pourra s&#39;appuyer sur des données de performance réelles. En attendant, deux garde-fous sont actés dès maintenant, non négociables dans l&#39;implémentation du Provider Manager :</p><ol><li>La dimension <code>pgvector</code> est <strong>verrouillée au premier modèle d&#39;embedding effectivement déployé</strong> en production — pas choisie arbitrairement à l&#39;avance.</li><li>Le Provider Manager doit <strong>refuser techniquement</strong> un changement de modèle d&#39;embedding tant qu&#39;une réindexation complète de <code>ai_embeddings</code> n&#39;est pas planifiée et exécutée — un changement de modèle est traité comme une migration de schéma, jamais comme un simple changement de configuration (cf. CDC §14.2, repris tel quel).</li></ol><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Choisir un modèle local dès maintenant</strong> (ex. via Ollama)</td><td>Écartée : fixerait une dimension <code>pgvector</code> sans aucune donnée de performance en français, avec un risque de devoir tout remettre en cause dès l&#39;Epic E8 — un coût de réindexation payé pour rien.</td></tr><tr><td><strong>Choisir un modèle cloud par défaut</strong></td><td>Écartée d&#39;emblée : contredit le mode <code>AI_SOVEREIGNTY_MODE=restricted</code> retenu par défaut (§14.8 du CDC) et le principe n°9 (souveraineté vérifiable de la donnée).</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Aucune dette technique créée par un choix prématuré et non informé.</li><li>Le principe de non-négociabilité de la réindexation est acté dès maintenant, avant qu&#39;un seul embedding ne soit produit — il ne pourra pas être contourné « pour aller vite » plus tard sous pression de planning.</li></ul><p><strong>Négatives</strong></p><ul><li>Le schéma <code>ai_embeddings</code> ne peut pas être figé avant l&#39;Epic E8 — toute Epic antérieure qui aurait besoin d&#39;embeddings (aucune identifiée dans le plan actuel avant E8/E9) devrait attendre.</li><li>Reporte une inconnue réelle : le jour où E8 démarre, le choix devra être fait rapidement pour ne pas bloquer la suite (E9, E13 Recherche complète en dépendent).</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] À l&#39;ouverture de l&#39;Epic E8, produire un comparatif de modèles d&#39;embedding candidats (locaux et cloud), avec au minimum : couverture du français, dimension, coût, capacité d&#39;auto-hébergement. <strong>Close.</strong> Le socle E8 (M8a) n&#39;avait d&#39;abord élu aucun modèle : le Model Registry (<code>apps/api/app/ai/catalogue/models.yaml</code>) décrivait des candidats marqués <code>status: candidate</code> — <code>nomic-embed-text</code> (768), <code>bge-m3</code> (1024), <code>text-embedding-3-small</code> (1536) — sans en désigner un, et <code>AI_DEFAULT_EMBEDDING_MODEL</code> restait vide. → <strong>Tranchée le 19/09/2026 par l&#39;<a href="/teuthis-cms-distribution/developpeurs/adr/0037-modele-embedding-par-defaut-bge-m3">ADR-0037</a></strong> : comparatif sur les quatre critères ci-dessus, <code>ollama/bge-m3</code> proposé par défaut, sans affaiblir les deux garde-fous de cette ADR. L&#39;évaluation sur un corpus réel reste une action de l&#39;ADR-0037.</li><li>[x] Implémenter le refus technique de changement de modèle sans réindexation planifiée comme critère de Definition of Done de E8, pas comme une amélioration ultérieure. <strong>Livré avec l&#39;Epic E8</strong> : <ul><li><code>apps/api/app/ai/embeddings.py</code> — <code>assert_embedding_model_allowed()</code> refuse tout modèle différent de celui qui a produit l&#39;index tant qu&#39;une réindexation ne le vise pas (<code>ai_jobs</code>, statut <code>planned</code>/<code>running</code>), et refuse dans tous les cas une dimension qui ne correspond pas à celle déjà écrite. Le refus est opposé à deux endroits — à la configuration (<code>app/ai/administration.py</code>, pose d&#39;une politique) <em>et</em> à l&#39;écriture des vecteurs — pour qu&#39;un chemin de code ne puisse pas contourner le premier.</li><li><code>apps/api/alembic/versions/0009_ai_socle.py</code> — <code>ai_embeddings.embedding</code> est un <code>vector</code> <strong>sans dimension déclarée</strong> : la dimension se verrouille au premier modèle effectivement déployé (point 1 ci-dessus), et l&#39;index <code>ivfflat</code>/<code>hnsw</code> ne se pose qu&#39;avec la migration qui la verrouille. C&#39;est précisément ce qui fait d&#39;un changement de modèle une migration.</li><li><code>apps/api/tests/test_ai_socle.py::test_changer_de_modele_d_embedding_sans_reindexation_est_refuse</code> — vérification mécanique, y compris la coexistence des deux modèles pendant la bascule et la suppression des vecteurs de l&#39;ancien à la clôture.</li></ul></li></ul>',17)])])}const g=d(i,[["render",o]]);export{p as __pageData,g as default};
